css = '''@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Inter,"DejaVu Sans",sans-serif;color:#16203a;font-size:10.6pt;line-height:1.32;margin:0}
.pg{page-break-after:always}.hd{background:#1f4e9c;color:#fff;border-radius:10px;padding:10px 14px;margin-bottom:8px}.hd h1{margin:0;font-size:17pt}.hd p{margin:2px 0 0;opacity:.9;font-size:9.5pt}
.grid{columns:2;column-gap:10px}.s{break-inside:avoid;border:1.5px solid #d9dfea;border-radius:8px;padding:7px 10px;margin-bottom:8px}.s h2{margin:0 0 4px;font-size:11.5pt;color:#1f4e9c}
ul{margin:0;padding-left:15px}li{margin:2px 0}.ft{margin-top:4px;font-size:8.5pt;color:#5b6680;text-align:center}'''
html = '<html><head><meta charset="utf-8"><style>' + css + '</style></head><body>'
for lg in ('uk', 'ru'):
    t = T[lg]
    html += f'<div class="pg"><div class="hd"><h1>✅ {t["title"]}</h1><p>{t["sub"]}</p></div><div class="grid">'
    for h, items in t['secs']:
        html += f'<div class="s"><h2>{h}</h2><ul>' + ''.join(f'<li>{x}</li>' for x in items) + '</ul></div>'
    html += f'</div><div class="ft">{t["foot"]}</div></div>'
open('c.html', 'w').write(html + '</body></html>')
